CREATE DATABASE IF NOT EXISTS amar_dayal_clinic CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE amar_dayal_clinic;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('Admin','Reception','Doctor') NOT NULL,full_name VARCHAR(150),active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients(id INT AUTO_INCREMENT PRIMARY KEY,code INT UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,age VARCHAR(10),gender VARCHAR(20),email VARCHAR(160),phone VARCHAR(30) NOT NULL,address TEXT,area VARCHAR(100),district VARCHAR(100),chronic_conditions TEXT,password VARCHAR(255),reset_token VARCHAR(255),reset_expires DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,name VARCHAR(150),email VARCHAR(160),phone VARCHAR(30),service VARCHAR(150),date DATE,time VARCHAR(80),status ENUM('Pending','Approved','Rejected','Completed') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS visits(id INT AUTO_INCREMENT PRIMARY KEY,opd_serial INT UNIQUE NOT NULL,appointment_id INT NULL,patient_id INT NOT NULL,visit_date DATE,main_conditions TEXT,symptoms TEXT,duration_number VARCHAR(20),duration_unit VARCHAR(20),fee_required TINYINT(1) DEFAULT 1,fee_amount DECIMAL(10,2) DEFAULT 0,fee_paid_date DATE,status ENUM('Pending','Completed') DEFAULT 'Pending',diagnosis TEXT,prescription TEXT,lab_tests TEXT,consulted_at DATETIME,created_by VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY(appointment_id) REFERENCES appointments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS bills(id INT AUTO_INCREMENT PRIMARY KEY,invoice_no VARCHAR(50) UNIQUE NOT NULL,patient_id INT NOT NULL,visit_id INT NULL,bill_date DATE,category VARCHAR(80),total_amount DECIMAL(10,2),discount DECIMAL(10,2) DEFAULT 0,net_amount DECIMAL(10,2),payment_mode VARCHAR(50),notes TEXT,created_by VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bill_items(id INT AUTO_INCREMENT PRIMARY KEY,bill_id INT NOT NULL,item_name VARCHAR(200),quantity INT DEFAULT 1,unit_price DECIMAL(10,2),total_price DECIMAL(10,2),FOREIGN KEY(bill_id) REFERENCES bills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reports(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,visit_id INT NULL,file_path VARCHAR(255),original_name VARCHAR(255),uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100),action VARCHAR(100),details TEXT,timestamp DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),email VARCHAR(160),phone VARCHAR(30),message TEXT,date DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_content(id INT AUTO_INCREMENT PRIMARY KEY,content_key VARCHAR(100) UNIQUE NOT NULL,content_value TEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clinic_services(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150),description TEXT,icon VARCHAR(20) DEFAULT '🩺',is_active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clinic_gallery(id INT AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(255),title VARCHAR(150),caption TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO site_content(content_key,content_value) VALUES('home_title','Relief From Pain Starts Here'),('home_subtitle','Professional Pain Relief & Physiotherapy Clinic'),('home_button','Book Appointment'),('about_description','Amar Dayal Clinic is dedicated to quality pain relief treatment and physiotherapy care.'),('doctor_name','Dr. Amar Dayal'),('doctor_speciality','Pain Relief Specialist'),('doctor_description','Experienced in pain management, joint problems and physical rehabilitation.'),('contact_address','Nagala Pajaba, Kurawali Rd, near Mahila Thana Chok, Nagla Pazawa, Hindpuram Colony, Mainpuri, Uttar Pradesh 205001'),('contact_phone','+91 9359848526'),('contact_hours','Monday - Saturday | 9:00 AM - 6:00 PM') ON DUPLICATE KEY UPDATE content_value=VALUES(content_value);
